update public.packages set slug = 'online-coaching', name = 'Online coaching', short_name = 'Online coaching', badge = null, tagline = 'Klasični online coaching uz tjedni check-in i stalno prilagođavanje plana.', audience = 'Za one koji žele redovito praćenje i plan koji se mijenja zajedno s njima.', price = 180, price_unit = 'mjesečno', price_note = 'Plaća se mjesečno', check_in = 'Check-in svakih 7 dana', features = array['Početni plan treninga i prehrane prema upitniku', 'Check-in i izmjene svakih 7 dana', 'Dostupan za pitanja između check-inova']::text[], includes = '[{"title":"Upitnik i početni plan","text":"Detaljan upitnik o tvom stanju, rutini i ciljevima, a zatim plan treninga i prehrane složen prema njemu."},{"title":"Check-in svakih 7 dana","text":"Šalješ slike i podatke, a ja na temelju njih postavljam sve parametre za sljedeći tjedan."},{"title":"Stalna prilagodba","text":"Trening, prehrana i suplementacija mijenjaju se kad tijelo krene drugačije od plana."},{"title":"Pitanja između check-inova","text":"Radnim danima sam na raspolaganju za sva pitanja vezana uz sam proces."}]'::jsonb where slug in ('online-coaching', 'online-coaching');
update public.packages set slug = 'paket-12-tjedana', name = 'Paket 12 tjedana', short_name = '12 tjedana', badge = 'Za početnike', tagline = 'Napredak bez pritiska. Plan koji se uklapa u tvoj život, a ne obrnuto.', audience = 'Za početnike i srednje iskusne koji žele rezultat bez spartanskog pristupa.', price = 380, price_unit = 'za 12 tjedana', price_note = 'Plaća se jednom unaprijed, za sva 3 mjeseca', check_in = 'Check-in svaka 4 tjedna', features = array['Početni plan treninga i prehrane prema upitniku', '3 check-ina, svaka 4 tjedna, putem e-maila', 'Bez odricanja od svega i bez spartanskog režima']::text[], includes = '[{"title":"Upitnik i polazni plan","text":"Plan treninga i prehrane složen prema tvom stanju, rutini i navikama kojih se ne želiš odreći."},{"title":"3 check-ina u 12 tjedana","text":"Svaka 4 tjedna šalješ check-in, a ja prilagodim plan za sljedeće razdoblje."},{"title":"Tempo koji sam biraš","text":"Sustav radi onoliko koliko mu se posvetiš. Može donijeti male pomake ili iznadprosječnu transformaciju."},{"title":"Nastavak po želji","text":"Nakon 12 tjedana produžiš isti paket ili prijeđeš na online coaching s tjednim check-inom."}]'::jsonb where slug in ('paket-12-tjedana', 'paket-12-sedmica');
update public.packages set slug = 'coaching-i-edukacija', name = 'Coaching i edukacija', short_name = 'Coaching i edukacija', badge = null, tagline = 'Učiš kroz praksu, na stvarnoj transformaciji, korak po korak.', audience = 'Za trenere i iskusnije vježbače koji žele razumjeti cijeli proces.', price = 350, price_unit = 'mjesečno', price_note = 'Coaching i edukacija u istoj cijeni', check_in = 'Proces vodimo zajedno', features = array['Kompletan coaching proces i edukacija u jednom', 'Radimo na tebi ili na tvom klijentu', 'Svaka odluka objašnjena do detalja']::text[], includes = '[{"title":"Coaching kroz cijeli proces","text":"Transformacija tebe ili tvog klijenta, s planom treninga i prehrane i redovitim izmjenama."},{"title":"Objašnjenje svakog koraka","text":"Za svaku izmjenu znaš zašto se radi, kako se donosi odluka i što se očekuje."},{"title":"Rješavanje stagnacije","text":"Kroz stvarne situacije pokazujem kako se prepoznaje i rješava zastoj u napretku."},{"title":"Pitanja kad god zatrebaju","text":"Na raspolaganju sam i za sva dodatna pitanja vezana uz trening i prehranu."}]'::jsonb where slug in ('coaching-i-edukacija', 'coaching-i-edukacija');
update public.packages set slug = 'natjecateljske-pripreme', name = 'Natjecateljske pripreme', short_name = 'Natjecateljske pripreme', badge = null, tagline = 'Priprema za natjecanje od trenera čiji su natjecatelji osvojili sve u amaterskom bodybuildingu.', audience = 'Za natjecatelje, od prvog nastupa do pro karte.', price = 220, price_unit = 'mjesečno', price_note = 'Plaća se mjesečno', check_in = 'Plan do dana natjecanja', features = array['Priprema za konkretno natjecanje i datum', 'Trening, prehrana i završnica pred nastup', 'Pomoć oko pozinga po dogovoru']::text[], includes = '[{"title":"Plan za cijelu pripremu","text":"Trening, prehrana i suplementacija složeni prema datumu nastupa i tvom iskustvu."},{"title":"Završnica do detalja","text":"Zadnji tjedni i dani pred nastup, gdje se priprema dobiva ili gubi."},{"title":"Pozing po dogovoru","text":"Ako ti treba pomoć oko pozinga, navedeš to u upitniku pa se dogovorimo."},{"title":"Iskustvo s velikih pozornica","text":"Arnold Classic, svjetsko i europsko prvenstvo, četiri pro karte s natjecateljima."}]'::jsonb where slug in ('natjecateljske-pripreme', 'takmicarske-pripreme');
update public.applications set package_slug = 'paket-12-tjedana' where package_slug = 'paket-12-sedmica';
update public.applications set package_slug = 'natjecateljske-pripreme' where package_slug = 'takmicarske-pripreme';
